<script setup lang="ts">
/**
 * The credential fields of a storage connection (spec 038 US1, spec 050 US1, US4): access key and
 * secret for S3, username and password for WebDAV, and for SFTP a password or a key. A key is
 * pasted, read from a file, or generated by holzi (research R4): then the window gets only its
 * id and its public key to register at the provider; the private key stays in Rust until the
 * connection is saved and lands in the password manager (FR-008).
 */
import { invoke } from '@tauri-apps/api/core'
import { useClipboard } from '@vueuse/core'
import type { GeneratedKey } from '@bindings/GeneratedKey'
import type { Protocol } from '@bindings/Protocol'
import type { SettingsSelectOption } from '~/components/settings/Select.vue'
import type { CredentialsDraft } from './credentials'

const props = defineProps<{ protocol: Protocol }>()
const draft = defineModel<CredentialsDraft>({ required: true })
const { t } = useI18n()
const fieldLabels = useFieldLabels()
const storageError = useStorageError()
const { copy, copied } = useClipboard({ legacy: true })
const generating = ref(false)
const failure = ref<string | null>(null)

const methodOptions = computed<SettingsSelectOption[]>(() =>
  (['password', 'key'] as const).map((method) => ({
    value: method,
    label: t(`settings.storage.authMethods.${method}`),
  })),
)
const withKey = computed(
  () => props.protocol === 'sftp' && draft.value.authMethod === 'key',
)

async function generateAsync() {
  generating.value = true
  failure.value = null
  try {
    const key = await invoke<GeneratedKey>('storage_ssh_key_generate')
    draft.value.keyId = key.keyId
    draft.value.publicKey = key.publicKey
    draft.value.privateKey = ''
    draft.value.passphrase = ''
  } catch (error) {
    failure.value = storageError(error)
  } finally {
    generating.value = false
  }
}

async function readFileAsync(event: Event) {
  const file = (event.target as HTMLInputElement).files?.[0]
  if (!file) return
  draft.value.privateKey = await file.text()
  draft.value.keyId = ''
  draft.value.publicKey = ''
}

/** A pasted key replaces a generated one. */
function pasted(text: string) {
  draft.value.privateKey = text
  if (text) {
    draft.value.keyId = ''
    draft.value.publicKey = ''
  }
}
</script>

<template>
  <template v-if="protocol === 's3'">
    <li class="px-4 py-3">
      <UiInput
        id="storage-access-key"
        v-model="draft.accessKeyId"
        :label="t('settings.storage.fields.accessKeyId')"
        :labels="fieldLabels.input.value"
        label-bg="var(--muted)"
        autocomplete="off"
        data-testid="storage-access-key"
      />
    </li>
    <li class="px-4 py-3">
      <UiInputPassword
        id="storage-secret"
        v-model="draft.secretAccessKey"
        :label="t('settings.storage.fields.secretAccessKey')"
        :labels="fieldLabels.password.value"
        label-bg="var(--muted)"
        autocomplete="new-password"
        data-testid="storage-secret"
      />
    </li>
    <li class="px-4 py-3">
      <UiInputPassword
        id="storage-session-token"
        v-model="draft.sessionToken"
        :label="t('settings.storage.fields.sessionToken')"
        :labels="fieldLabels.password.value"
        label-bg="var(--muted)"
        autocomplete="off"
        data-testid="storage-session-token"
      />
    </li>
  </template>
  <template v-else>
    <li class="px-4 py-3">
      <UiInput
        id="storage-username"
        v-model="draft.username"
        :label="t('settings.storage.fields.username')"
        :labels="fieldLabels.input.value"
        label-bg="var(--muted)"
        autocomplete="off"
        data-testid="storage-username"
      />
    </li>
    <SettingsRow
      v-if="protocol === 'sftp'"
      :title="t('settings.storage.fields.authMethod')"
      label-for="storage-auth-method"
    >
      <SettingsSelect
        id="storage-auth-method"
        v-model="draft.authMethod"
        :options="methodOptions"
        data-testid="storage-auth-method"
      />
    </SettingsRow>
    <li v-if="!withKey" class="px-4 py-3">
      <UiInputPassword
        id="storage-password"
        v-model="draft.password"
        :label="t('settings.storage.fields.password')"
        :labels="fieldLabels.password.value"
        label-bg="var(--muted)"
        autocomplete="new-password"
        data-testid="storage-password"
      />
    </li>
    <template v-else>
      <li class="flex flex-col gap-2 px-4 py-3">
        <UiButton
          type="button"
          variant="outline"
          :loading="generating"
          data-testid="storage-generate-key"
          @click="generateAsync"
        >
          {{ t('settings.storage.actions.generateKey') }}
        </UiButton>
        <template v-if="draft.publicKey">
          <p class="text-sm text-muted-foreground">
            {{ t('settings.storage.generatedKeyHint') }}
          </p>
          <code
            class="rounded-md bg-background px-2 py-1 text-xs break-all"
            data-testid="storage-public-key"
            >{{ draft.publicKey }}</code
          >
          <UiButton
            type="button"
            variant="ghost"
            size="sm"
            data-testid="storage-copy-public-key"
            @click="copy(draft.publicKey)"
          >
            {{
              copied
                ? t('settings.storage.actions.copied')
                : t('settings.storage.actions.copyPublicKey')
            }}
          </UiButton>
        </template>
        <p v-if="failure" class="text-sm text-destructive" role="alert">
          {{ failure }}
        </p>
      </li>
      <li v-if="!draft.keyId" class="flex flex-col gap-2 px-4 py-3">
        <UiTextarea
          id="storage-private-key"
          :model-value="draft.privateKey"
          :label="t('settings.storage.fields.privateKey')"
          rows="4"
          class="font-mono text-xs"
          autocomplete="off"
          spellcheck="false"
          data-testid="storage-private-key"
          @update:model-value="pasted(String($event ?? ''))"
        />
        <label class="text-sm text-muted-foreground">
          {{ t('settings.storage.actions.readKeyFile') }}
          <input
            type="file"
            class="mt-1 block text-sm"
            data-testid="storage-key-file"
            @change="readFileAsync"
          />
        </label>
      </li>
      <li v-if="!draft.keyId" class="px-4 py-3">
        <UiInputPassword
          id="storage-passphrase"
          v-model="draft.passphrase"
          :label="t('settings.storage.fields.passphrase')"
          :labels="fieldLabels.password.value"
          label-bg="var(--muted)"
          autocomplete="off"
          data-testid="storage-passphrase"
        />
      </li>
    </template>
  </template>
</template>
